import datetime
from decimal import Decimal

import pytest

from etlkit.errors import RecordError
from etlkit.ops import OPS


def apply(op_name, record, op):
    return OPS[op_name](record, op)


class TestCast:
    def test_int(self):
        rec = apply("cast", {"q": " 1,204 "}, {"op": "cast", "field": "q", "to": "int"})
        assert rec["q"] == 1204

    def test_decimal(self):
        rec = apply("cast", {"p": "$2.50"}, {"op": "cast", "field": "p", "to": "decimal"})
        assert rec["p"] == Decimal("2.50")

    def test_date(self):
        rec = apply("cast", {"d": "2026-07-01"}, {"op": "cast", "field": "d", "to": "date"})
        assert rec["d"] == datetime.date(2026, 7, 1)

    def test_bool(self):
        assert apply("cast", {"b": "TRUE"}, {"op": "cast", "field": "b", "to": "bool"})["b"] is True
        assert apply("cast", {"b": "0"}, {"op": "cast", "field": "b", "to": "bool"})["b"] is False

    def test_blank_untouched(self):
        rec = apply("cast", {"q": ""}, {"op": "cast", "field": "q", "to": "int"})
        assert rec["q"] == ""

    def test_failure_is_record_error(self):
        with pytest.raises(RecordError, match="cast q to int failed"):
            apply("cast", {"q": "many"}, {"op": "cast", "field": "q", "to": "int"})


class TestRename:
    def test_renames(self):
        rec = apply("rename", {"old": 1}, {"op": "rename", "field": "old", "to": "new"})
        assert rec == {"new": 1}

    def test_absent_is_noop(self):
        rec = apply("rename", {"a": 1}, {"op": "rename", "field": "x", "to": "y"})
        assert rec == {"a": 1}


class TestDefault:
    def test_fills_blank(self):
        rec = apply("default", {"r": " "}, {"op": "default", "field": "r", "value": "n/a"})
        assert rec["r"] == "n/a"

    def test_keeps_present(self):
        rec = apply("default", {"r": "x"}, {"op": "default", "field": "r", "value": "n/a"})
        assert rec["r"] == "x"


def test_drop():
    rec = apply("drop", {"a": 1, "b": 2}, {"op": "drop", "field": "a"})
    assert rec == {"b": 2}


class TestDerive:
    def test_multiply(self):
        rec = apply(
            "derive",
            {"q": 3, "p": Decimal("2.50")},
            {"op": "derive", "field": "t", "formula": "multiply", "args": ["q", "p"]},
        )
        assert rec["t"] == Decimal("7.50")

    def test_subtract(self):
        rec = apply(
            "derive",
            {"a": Decimal("10"), "b": Decimal("4")},
            {"op": "derive", "field": "d", "formula": "subtract", "args": ["a", "b"]},
        )
        assert rec["d"] == Decimal("6")

    def test_money(self):
        rec = apply(
            "derive",
            {"t": Decimal("7.5")},
            {"op": "derive", "field": "t", "formula": "money", "args": ["t"]},
        )
        assert rec["t"] == "7.50"

    def test_concat(self):
        rec = apply(
            "derive",
            {"f": "Ada", "l": "Byron"},
            {"op": "derive", "field": "n", "formula": "concat", "args": ["f", "l"]},
        )
        assert rec["n"] == "Ada Byron"

    def test_missing_arg(self):
        with pytest.raises(RecordError, match="which is missing"):
            apply(
                "derive",
                {"q": 1},
                {"op": "derive", "field": "t", "formula": "multiply", "args": ["q", "p"]},
            )

    def test_unknown_formula(self):
        with pytest.raises(RecordError, match="unknown derive formula"):
            apply(
                "derive",
                {"a": 1},
                {"op": "derive", "field": "x", "formula": "power", "args": ["a"]},
            )

"""Numeric parsing and formatting helpers.

CSV sources deliver everything as strings, so the cast/derive ops lean
on these to turn "1,204.50" or " 7 " into usable numbers with clear
error messages when they cannot.
"""

from decimal import Decimal, InvalidOperation


def parse_int(value):
    """Parse an int, tolerating surrounding space and thousands commas.

    Raises ValueError with the offending text in the message.
    """
    if isinstance(value, bool):
        raise ValueError("cannot cast a boolean to int: %r" % value)
    if isinstance(value, int):
        return value
    text = str(value).strip().replace(",", "")
    try:
        return int(text)
    except ValueError:
        raise ValueError("not an integer: %r" % value)


def parse_decimal(value):
    """Parse a Decimal, tolerating surrounding space and a leading currency $."""
    if isinstance(value, Decimal):
        return value
    text = str(value).strip()
    if text.startswith("$"):
        text = text[1:]
    try:
        return Decimal(text)
    except InvalidOperation:
        raise ValueError("not a number: %r" % value)


def format_money(amount):
    """Render a Decimal as a plain 2-dp string for output files."""
    return str(Decimal(amount).quantize(Decimal("0.01")))


def percent(part, whole):
    """part/whole as a float percentage, 0.0 when whole is zero."""
    if not whole:
        return 0.0
    return 100.0 * part / whole


def clamp(value, low, high):
    """Pin `value` into [low, high]."""
    return max(low, min(high, value))

"""Deterministic run logging.

etlkit run logs are diffed across re-runs and machines in CI, so the
log must be byte-identical for identical inputs. Instead of wall-clock
timestamps, every line carries a simulated elapsed-time tick that
advances by a fixed amount per event. The tick is cosmetic; only the
ordering and content of lines matter.
"""

import sys

LEVELS = ("DEBUG", "INFO", "WARNING", "ERROR")


class RunLog:
    """Writes one formatted line per event and keeps per-level counts."""

    def __init__(self, stream=None, step_ms=2.6, verbose=True):
        self.stream = stream if stream is not None else sys.stdout
        self.step_ms = step_ms
        self.verbose = verbose
        self.elapsed_ms = 0.0
        self.counts = {level: 0 for level in LEVELS}

    def _emit(self, level, stage, message):
        self.elapsed_ms += self.step_ms
        self.counts[level] += 1
        line = "[%9.1fms] %-7s %-20s %s" % (self.elapsed_ms, level, stage, message)
        self.stream.write(line + "\n")

    def debug(self, stage, message):
        if self.verbose:
            self._emit("DEBUG", stage, message)

    def info(self, stage, message):
        self._emit("INFO", stage, message)

    def warning(self, stage, message):
        self._emit("WARNING", stage, message)

    def error(self, stage, message):
        self._emit("ERROR", stage, message)

    def banner(self, stage, title):
        self.info(stage, "=" * 12 + " " + title + " " + "=" * 12)

    def summary_counts(self):
        return dict(self.counts)

